#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Where captures land (relative to the repo root; run this from there).
# Latest finished EAS "preview" build (release APK); override with APK_URL=… if needed.
APK_URL="${APK_URL:-$(npx eas-cli build:list -p android --profile preview --status finished --limit 1 --non-interactive --json 2>/dev/null \
  | python3 -I -c 'import json,sys; b=json.load(sys.stdin); print((b[0].get("artifacts") or {}).get("buildUrl",""))')}"
PACKAGE="com.bartelspeter.voiceclaude"
SHOTS="store/screenshots"
VIDEOS="store/videos"
mkdir -p "$SHOTS" "$VIDEOS"

# shot NAME saves the phone screen as store/screenshots/NAME.png.
shot() {
  adb exec-out screencap -p > "$SHOTS/$1.png"
  printf '  %s✓ saved%s %s/%s.png\n' "$GREEN" "$RESET" "$SHOTS" "$1"
}

# record_start NAME starts a screen recording on the phone (3 min cap, no audio).
record_start() {
  adb shell rm -f "/sdcard/$1.mp4"
  adb shell screenrecord --time-limit 180 --bit-rate 6000000 "/sdcard/$1.mp4" &
  RECORD_PID=$!
  printf '  %s● recording%s %s.mp4 (stops by itself after 3 minutes)\n' "$RED" "$RESET" "$1"
}

# record_stop NAME ends the recording and pulls it to store/videos/NAME.mp4.
record_stop() {
  adb shell pkill -2 screenrecord >/dev/null 2>&1 || true
  wait "$RECORD_PID" 2>/dev/null || true
  sleep 2
  adb pull "/sdcard/$1.mp4" "$VIDEOS/$1.mp4" >/dev/null
  printf '  %s✓ saved%s %s/%s.mp4\n' "$GREEN" "$RESET" "$VIDEOS" "$1"
}

# Usage: store/record.sh [N]  — start at stage N (default 1), e.g. after a restart.
START_STAGE="${1:-1}"
_STAGE_INDEX=$((START_STAGE - 1))

stage_1() {
stage "Plug in the A54"
say "Captures come over adb, so the phone must be connected with USB debugging on."
step "Plug the phone in, unlock it, and accept the 'Allow USB debugging' prompt if it appears."
until adb devices | awk 'NR>1 && $2=="device"' | grep -q .; do
  pause "No device yet. Press Enter to check again."
done
say "Device: $(adb devices -l | awk 'NR==2{print $1, $4, $5}')"
pause
}

stage_2() {
stage "Install the preview build"
say "The recordings should show the release build (no dev server), the same one Play will see."
note "The dev build is signed with a different key, so replacing it means uninstalling first."
INSTALLED=false
if adb shell pm list packages 2>/dev/null | grep -q "^package:$PACKAGE$"; then
  if confirm "$PACKAGE is already on the phone. Keep it (y) or replace it with the preview build (N)?"; then
    INSTALLED=true
  else
    warn "Uninstalling removes the stored API keys and the Slack token; you'll re-enter them in the app."
    adb uninstall "$PACKAGE" >/dev/null 2>&1 || note "nothing to uninstall"
  fi
fi
if [[ "$INSTALLED" == false ]]; then
  APK=$(mktemp -d)/voice-claude-preview.apk
  [[ -n "$APK_URL" ]] || { warn "no finished preview build found on EAS; run: npx eas-cli build -p android --profile preview"; exit 1; }
  say "Downloading the latest preview APK from EAS (about 73 MB)…"
  curl -fL --progress-bar "$APK_URL" -o "$APK"
  step "Unlock the phone and keep it unlocked: Play Protect asks about the sideloaded app ('Don't send' is fine)."
  say "Installing…"
  adb install -r "$APK" | tail -1
  printf '  %s✓ installed%s preview build\n' "$GREEN" "$RESET"
fi
adb shell pm grant "$PACKAGE" android.permission.WRITE_SECURE_SETTINGS && \
  printf '  %s✓ granted%s WRITE_SECURE_SETTINGS (walk-mode toggle works without Settings)\n' "$GREEN" "$RESET"
step "Open Voice Claude on the phone, enter the Anthropic and Deepgram keys, and set it as the digital assistant."
pause "Done? Press Enter."
}

stage_3() {
stage "Screenshots (Play needs at least two)"
step "In Settings, switch 'Earbud opens the Claude app' ON so the Walk mode disclosure card shows, then save."
pause "Showing the disclosure card? Press Enter to capture."
shot "01-walk-mode-disclosure"
step "Switch the setting back OFF, tap Talk and ask Claude something so the transcript fills the screen."
pause "Transcript on screen? Press Enter to capture."
shot "02-conversation"
if confirm "Capture a third screenshot (any screen you like)?"; then
  pause "Press Enter when it's on screen."
  shot "03-extra"
fi
}

stage_4() {
stage "Video: accessibility service declaration"
say "Play wants to see: the disclosure, accepting it, enabling the service, and an earbud press driving the Claude app."
note "screenrecord captures the screen only, no audio; that is fine for this one."
step "Before recording: Settings → earbud opens the Claude app ON, save. Walk mode must be OFF (tile or icon shortcut)."
step "Have the earbuds in and connected."
pause "Ready? Press Enter to start recording, then do the steps on the phone."
record_start "accessibility-service"
step "1. Show the main screen with the disclosure card. Tap 'Agree and turn on Walk mode'."
step "2. If Android Settings opens instead, enable 'Voice Claude earbud tap' there and go back."
step "3. Lock the phone, long-press the earbud: the Claude app opens and voice mode starts, then the screen locks."
step "4. Unlock and show the Claude app with voice mode on."
pause "Finished the steps? Press Enter to stop recording."
record_stop "accessibility-service"
}

stage_5() {
stage "Video: microphone foreground service declaration"
say "Play wants to see: an earbud press starting a conversation with the screen locked, the ongoing notification, and the spoken answer."
note "screenrecord has no audio. If you want the answer audible, use Samsung's own screen recorder"
note "(Quick Settings → Screen recorder, sound: Media) instead and pull the file from /sdcard/DCIM/Screen recordings."
step "Before recording: Settings → earbud opens the Claude app OFF (Voice Claude's own conversation), save."
pause "Ready? Press Enter to start recording."
record_start "microphone-foreground-service"
step "1. Lock the phone. Long-press the earbud and ask a question."
step "2. Wake the screen (don't unlock yet) so the lock screen shows the 'Claude is listening' notification."
step "3. Unlock: the main screen shows the transcript while the answer is spoken. Say 'that's all'."
pause "Finished? Press Enter to stop recording."
record_stop "microphone-foreground-service"
}

stage_6() {
stage "Optional: capture Claude app labels for the chat-search item"
say "The deferred 'resume a chosen past chat by voice' item needs the content descriptions of Claude's chat list and search."
if confirm "Capture them now (about a minute)?"; then
  adb logcat -c
  adb logcat -s VoiceClaude > "store/claude-labels.log" &
  LOG_PID=$!
  step "Walk mode ON, earbud mode ON. Long-press the earbud, then within 20 seconds open the Claude app's"
  step "chat list (menu / back), tap the search field, type a word, and open a result."
  pause "Done? Press Enter to stop logging."
  kill "$LOG_PID" 2>/dev/null || true
  printf '  %s✓ saved%s store/claude-labels.log (%s lines); paste the 'labels on screen' lines into the doc item\n' \
    "$GREEN" "$RESET" "$(wc -l < store/claude-labels.log)"
fi
}

banner "Play Console recordings for Voice Claude"
for n in $(seq "$START_STAGE" "$TOTAL_STAGES"); do "stage_$n"; done

finish
say "Upload in the Play Console:"
note "  Store listing → Phone screenshots: $SHOTS/*.png"
note "  App content → Accessibility: $VIDEOS/accessibility-service.mp4"
note "  App content → Foreground service permissions: $VIDEOS/microphone-foreground-service.mp4"
